create extension if not exists pgcrypto;
create table if not exists public.daily_reports (id text primary key, project_id text not null default 'khayrat', report_date date, workshop text, process text, activity_id text, source_file text, payload jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.image_evidence (image_id text primary key, project_id text not null default 'khayrat', report_id text references public.daily_reports(id) on delete set null, source_file text, page_number integer, payload jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.import_audits (import_id uuid primary key default gen_random_uuid(), project_id text not null default 'khayrat', user_id uuid default auth.uid(), files jsonb not null default '[]', result jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.progress_measurements (id text primary key, project_id text not null default 'khayrat', source_file text, payload jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.equipment_shipments (id text primary key, project_id text not null default 'khayrat', source_file text, payload jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.crosswalk_mappings (id text primary key, project_id text not null default 'khayrat', source_file text, payload jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists progress_measurements_project_idx on public.progress_measurements(project_id);
create index if not exists equipment_shipments_project_idx on public.equipment_shipments(project_id);
create index if not exists crosswalk_mappings_project_idx on public.crosswalk_mappings(project_id);
alter table public.daily_reports enable row level security;alter table public.image_evidence enable row level security;alter table public.import_audits enable row level security;alter table public.progress_measurements enable row level security;alter table public.equipment_shipments enable row level security;alter table public.crosswalk_mappings enable row level security;
create policy "authenticated reports" on public.daily_reports for all to authenticated using (true) with check (true);
create policy "authenticated evidence" on public.image_evidence for all to authenticated using (true) with check (true);
create policy "authenticated audits" on public.import_audits for all to authenticated using (true) with check (true);
create policy "authenticated progress" on public.progress_measurements for all to authenticated using (true) with check (true);
create policy "authenticated shipments" on public.equipment_shipments for all to authenticated using (true) with check (true);
create policy "authenticated mappings" on public.crosswalk_mappings for all to authenticated using (true) with check (true);
grant select,insert,update,delete on public.progress_measurements,public.equipment_shipments,public.crosswalk_mappings to authenticated;
insert into storage.buckets(id,name,public) values('khayrat-reports','khayrat-reports',false) on conflict(id) do update set public=false;
create policy "authenticated report objects" on storage.objects for all to authenticated using(bucket_id='khayrat-reports') with check(bucket_id='khayrat-reports');
